package com.travel.meomulkyung.itinerary.controller;
import com.travel.meomulkyung.itinerary.dto.*; import com.travel.meomulkyung.itinerary.service.ItineraryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/itineraries") @RequiredArgsConstructor public class ItineraryController {private final ItineraryService service; @PostMapping @ResponseStatus(HttpStatus.CREATED) public ItineraryResponses.Itinerary create(@AuthenticationPrincipal Long u,@Valid @RequestBody ItineraryRequests.Create r){return service.create(u,r);} @GetMapping("/{id}") public ItineraryResponses.Itinerary get(@AuthenticationPrincipal Long u,@PathVariable Long id){return service.get(u,id);} @PostMapping("/{id}/items/{itemId}/replace") public ItineraryResponses.Replacement replace(@AuthenticationPrincipal Long u,@PathVariable Long id,@PathVariable Long itemId,@RequestBody(required=false) ItineraryRequests.Replace r){return service.replace(u,id,itemId,r==null?new ItineraryRequests.Replace(false):r);} @PostMapping("/{id}/regenerate") public ItineraryResponses.Itinerary regenerate(@AuthenticationPrincipal Long u,@PathVariable Long id,@RequestBody(required=false) ItineraryRequests.Replace r){return service.regenerate(u,id,r==null?new ItineraryRequests.Replace(false):r);} @PutMapping("/{id}/bookmark") public ItineraryResponses.Bookmark bookmark(@AuthenticationPrincipal Long u,@PathVariable Long id){return service.bookmark(u,id);} @DeleteMapping("/{id}/bookmark") @ResponseStatus(HttpStatus.NO_CONTENT) public void unbookmark(@AuthenticationPrincipal Long u,@PathVariable Long id){service.unbookmark(u,id);} @PostMapping("/{id}/completion") @ResponseStatus(HttpStatus.CREATED) public ItineraryResponses.Completion complete(@AuthenticationPrincipal Long u,@PathVariable Long id,@Valid @RequestBody ItineraryRequests.Completion r){return service.complete(u,id,r);} @GetMapping("/{id}/weather") public ItineraryResponses.WeatherDays weather(@AuthenticationPrincipal Long u,@PathVariable Long id){return service.weather(u,id);}}
